/* Four creation modes with editable, local-first results. */
(function(){'use strict';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],C=()=>window.NotaCreative;
function shell(n,c,title,body,extra=''){c.modal(title,`<input id="mode-title" class="editor-title" value="${c.esc(n.title)}" maxlength="200" aria-label="Note title">${body}<button id="mode-ai" class="secondary mode-assist"><i data-lucide="sparkles"></i> Writing companion</button>`,`<button id="mode-export" class="secondary">Export text</button>${extra}<button id="mode-done" class="primary">Save to workspace</button>`,true,n);$('#mode-ai').onclick=()=>c.assistant(n);$('#mode-export').onclick=()=>c.export(n);$('#mode-done').onclick=c.finish;}
function common(n,c,mirror,cleanup=()=>{}){const persist=()=>{n.title=$('#mode-title').value.trim()||'Untitled note';n.html=mirror();c.touch(n);};$('#mode-title').oninput=persist;c.persist(persist);c.cleanup(cleanup);return persist;}
function journal(n,c){const j=n.journal;let tab=j.tab;
 shell(n,c,'Daily journal',`<div class="journal-date-row"><div class="field"><label for="journal-date">A page for</label><input id="journal-date" type="date" value="${j.date}" min="1900-01-01" max="2199-12-31"></div><p class="hint">One page per day in this workspace. Come back to the same thread.</p></div><fieldset class="journal-weather"><legend>How does today feel? <span class="hint">Optional</span></legend>${['quiet','steady','bright','busy','heavy'].map(m=>`<button type="button" data-journal-mood="${m}" aria-pressed="${j.mood===m}">${m[0].toUpperCase()+m.slice(1)}</button>`).join('')}</fieldset><div class="mode-tabs" role="tablist" aria-label="Journal space">${[['morning','Morning'],['evening','Evening'],['free','Free writing']].map(([v,t])=>`<button role="tab" data-journal-tab="${v}" aria-selected="${tab===v}">${t}</button>`).join('')}</div><p id="journal-prompt" class="hint"></p><div id="journal-fields"></div><section class="journal-next"><div class="field"><label for="journal-next">One small step for tomorrow</label><input id="journal-next" maxlength="2000" value="${c.esc(j.fields.next)}" placeholder="Something small enough to begin"></div><button id="journal-task" class="secondary"><i data-lucide="list-plus"></i> Make it a task</button></section><p class="hint">A private page, without a score or a streak to keep up. Entries save as you write.</p>`);
 const persist=common(n,c,()=>C().journalHTML(j));const prompt=()=>{const prompts=['What did you notice that you might otherwise forget?','What deserves a little more room in your day?','Which small moment would you like to keep?'];$('#journal-prompt').textContent=prompts[Number(j.date.replace(/-/g,''))%prompts.length];};
 const render=()=>{const keys={morning:['focus','space'],evening:['win','release'],free:['free']}[tab];$('#journal-fields').innerHTML=keys.map(k=>`<div class="field"><label for="journal-${k}">${C().journalFields[k]}</label><textarea id="journal-${k}" data-journal-field="${k}" rows="${k==='free'?12:5}" maxlength="20000" placeholder="Start wherever you are…">${c.esc(j.fields[k])}</textarea></div>`).join('');$$('[data-journal-field]').forEach(el=>el.oninput=()=>{j.fields[el.dataset.journalField]=el.value;persist();});$$('[data-journal-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.journalTab===tab)));prompt();};
 $$('[data-journal-mood]').forEach(b=>b.onclick=()=>{j.mood=j.mood===b.dataset.journalMood?'':b.dataset.journalMood;$$('[data-journal-mood]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.journalMood===j.mood)));persist();});$$('[data-journal-tab]').forEach(b=>b.onclick=()=>{tab=j.tab=b.dataset.journalTab;render();persist();});$('#journal-next').oninput=()=>{j.fields.next=$('#journal-next').value;$('#journal-task').disabled=!j.fields.next.trim();persist();};$('#journal-task').disabled=!j.fields.next.trim();$('#journal-task').onclick=()=>{persist();c.promote({id:j.taskId,title:'One small step · '+j.date,text:j.fields.next,task:true,parent:n,onId:id=>j.taskId=id});};$('#journal-date').onchange=()=>{const date=$('#journal-date').value;if(!C().validDate(date)||date<'1900-01-01'||date>'2199-12-31'){$('#journal-date').value=j.date;c.toast('Choose a date between 1900 and 2199.');return;}if(date!==j.date){persist();c.openJournal(date);}};render();c.icons();
}
function math(n,c){const sheet=n.mathSheet;const showNumber=v=>new Intl.NumberFormat(navigator.language?.split('@')[0].replace(/_/g,'-')||'en-US',{maximumSignificantDigits:12}).format(v);
 shell(n,c,'Math sheet',`<p class="mode-lead">Give each number a name. Let the next line build on it.</p><p class="hint">Use +, −, *, /, ^, %, parentheses, pi and e. Names can refer to other lines. Units are labels; convert values before mixing units.</p><div class="math-scenario-head"><button id="math-scenario" class="secondary" aria-pressed="${sheet.scenario}"><i data-lucide="git-compare-arrows"></i> What if?</button><p class="hint">Try a different value and follow its effect through the sheet.</p></div><div id="math-rows" class="math-rows"></div><button id="math-add" class="secondary"><i data-lucide="plus"></i> Add a calculation</button><p class="hint">Answers update as you type. Each result includes the substituted numbers, so you can check the working. These are arithmetic calculations, not AI answers.</p>`);
 const persist=common(n,c,()=>C().mathHTML(sheet,c.calculate));
 const results=()=>{const base=C().mathRun(sheet.rows,c.calculate),alt=sheet.scenario?C().mathRun(sheet.rows,c.calculate,true):[];for(let i=0;i<sheet.rows.length;i++){const el=$(`[data-math-result="${sheet.rows[i].id}"]`),r=sheet.rows[i],b=base[i],a=alt[i];el.innerHTML=`<div class="math-answer ${b.error?'math-error':''}">${b.error?c.esc(b.error):`<strong>${c.esc(showNumber(b.value))}</strong> <span>${c.esc(r.unit)}</span>`}</div>${b.error?'':`<details><summary>Show working</summary><code>${c.esc(r.expression)} → ${c.esc(b.expanded)} = ${c.esc(String(b.value))}</code></details>`}${sheet.scenario?`<div class="math-alternate"><span>What if</span> ${a.error?c.esc(a.error):`<strong>${c.esc(showNumber(a.value))}</strong> ${c.esc(r.unit)}${!b.error?`<small>Change: ${a.value-b.value>0?'+':''}${c.esc(showNumber(a.value-b.value))}</small>`:''}`}</div>`:''}`;}persist();};
 const render=()=>{$('#math-rows').innerHTML=sheet.rows.map((r,i)=>`<section class="math-line"><header><span>Line ${i+1}</span><button data-math-remove="${r.id}" class="icon-button" aria-label="Remove calculation line ${i+1}" ${sheet.rows.length===1?'disabled':''}><i data-lucide="trash-2"></i></button></header><div class="math-line-fields"><label>Label<input data-math-field="label" data-row="${r.id}" value="${c.esc(r.label)}" maxlength="100" placeholder="What does this number mean?"></label><label>Name<input data-math-field="name" data-row="${r.id}" value="${c.esc(r.name)}" maxlength="20" autocapitalize="none" spellcheck="false" placeholder="total"></label><label class="math-expression">Expression<input data-math-field="expression" data-row="${r.id}" value="${c.esc(r.expression)}" maxlength="180" autocapitalize="none" spellcheck="false" placeholder="guests * cost"></label><label>Unit (optional)<input data-math-field="unit" data-row="${r.id}" value="${c.esc(r.unit)}" maxlength="24" placeholder="people, cm, dollars…"></label>${sheet.scenario?`<label class="math-what-if">What if instead…<input data-math-field="whatIf" data-row="${r.id}" value="${c.esc(r.whatIf)}" maxlength="180" autocapitalize="none" spellcheck="false" placeholder="Leave blank to keep the original"></label>`:''}</div><div data-math-result="${r.id}" class="math-result" aria-live="polite"></div></section>`).join('');$$('[data-math-field]').forEach(el=>el.oninput=()=>{const row=sheet.rows.find(r=>r.id===el.dataset.row);row[el.dataset.mathField]=el.value;results();});$$('[data-math-remove]').forEach(b=>b.onclick=()=>{sheet.rows=sheet.rows.filter(r=>r.id!==b.dataset.mathRemove);render();});$('#math-add').disabled=sheet.rows.length>=50;$('#math-scenario').setAttribute('aria-pressed',String(sheet.scenario));results();c.icons();};
 $('#math-add').onclick=()=>{if(sheet.rows.length>=50)return;let number=sheet.rows.length+1;while(sheet.rows.some(r=>r.name==='value'+number))number++;sheet.rows.push({id:c.uid(),label:'',name:'value'+number,expression:'',whatIf:'',unit:''});render();$$('[data-math-field=expression]').at(-1).focus();};$('#math-scenario').onclick=()=>{sheet.scenario=!sheet.scenario;render();};render();
}
function mindmap(n,c){const map=n.mindmap;let selected=map.nodes.some(p=>p.id===map.selected)?map.selected:map.nodes[0].id,drag=null,history=[],future=[];
 shell(n,c,'Mind map',`<p class="mode-lead">Give a thought somewhere to lead.</p><p class="hint">Select a thought to name it, add a branch, or describe its connection. Drag the grip to move it. Arrow keys move a focused thought in small steps.</p><div class="map-toolbar"><button id="map-add" class="primary"><i data-lucide="plus"></i> Add branch</button><button id="map-arrange" class="secondary">Arrange branches</button><button id="map-undo" class="secondary" aria-label="Undo map edit"><i data-lucide="undo-2"></i></button><button id="map-redo" class="secondary" aria-label="Redo map edit"><i data-lucide="redo-2"></i></button></div><div id="map-scroll" class="map-scroll" aria-label="Mind map. Scroll to explore"><div id="map-stage" class="map-stage"></div></div><section class="map-detail"><h3>Selected thought</h3><div class="field"><label for="map-label">Thought</label><input id="map-label" maxlength="120"></div><div class="row"><div class="field"><label for="map-parent">Connect from</label><select id="map-parent"></select></div><div class="field"><label for="map-relation">How does it connect?</label><input id="map-relation" maxlength="60" placeholder="because, leads to, what if…"></div></div><div class="field"><label for="map-body">Give it a little more room</label><textarea id="map-body" maxlength="4000" rows="4"></textarea></div><div class="map-promote"><button id="map-note" class="secondary">Open as note</button><button id="map-task" class="secondary">Make it a task</button><button id="map-delete" class="danger">Remove branch</button></div><div id="map-delete-choice" class="inline-choice" hidden><p id="map-delete-copy"></p><button id="map-delete-cancel" class="secondary">Cancel</button><button id="map-delete-confirm" class="danger">Remove branch</button></div></section><details class="map-outline"><summary>Text outline</summary><div id="map-outline"></div></details>`);
 const persist=common(n,c,()=>C().mapHTML(map),()=>{drag=null;});const current=()=>map.nodes.find(p=>p.id===selected)||map.nodes[0];
 const remember=()=>{history.push(structuredClone(map.nodes));history=history.slice(-25);future=[];};
 const controls=()=>{$('#map-undo').disabled=!history.length;$('#map-redo').disabled=!future.length;$('#map-add').disabled=map.nodes.length>=60;$('#map-delete').disabled=current().parent===null;$('#map-parent').disabled=current().parent===null;$('#map-relation').disabled=current().parent===null;};
 const draw=()=>{const w=Math.max(900,...map.nodes.map(p=>p.x+200)),h=Math.max(560,...map.nodes.map(p=>p.y+105));$('#map-stage').style.width=w+'px';$('#map-stage').style.height=h+'px';$('#map-stage').innerHTML=C().mapSVG(map)+map.nodes.map(p=>`<button class="map-node ${p.id===selected?'chosen':''}" data-map-node="${p.id}" style="left:${p.x}px;top:${p.y}px" aria-pressed="${p.id===selected}"><span data-map-grip aria-hidden="true">⠿</span><strong>${c.esc(p.label||'Untitled thought')}</strong><small>${c.esc(p.body.slice(0,60)||'A little room to explore')}</small></button>`).join('');$$('[data-map-node]').forEach(b=>{b.onclick=()=>select(b.dataset.mapNode);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();remember();const p=map.nodes.find(p=>p.id===b.dataset.mapNode);p.x=Math.max(0,Math.min(2200,p.x+(e.key==='ArrowLeft'?-16:e.key==='ArrowRight'?16:0)));p.y=Math.max(0,Math.min(8000,p.y+(e.key==='ArrowUp'?-16:e.key==='ArrowDown'?16:0)));selected=p.id;map.selected=selected;draw();persist();controls();$(`[data-map-node="${p.id}"]`).focus({preventScroll:true});};b.onpointerdown=e=>{if(!e.target.closest('[data-map-grip]')||e.isPrimary===false||e.button!==0)return;e.preventDefault();selected=b.dataset.mapNode;map.selected=selected;remember();const p=current();drag={id:e.pointerId,button:b,startX:e.clientX,startY:e.clientY,x:p.x,y:p.y,node:p};try{b.setPointerCapture(e.pointerId);}catch{}panel();};b.onpointermove=e=>{if(!drag||drag.id!==e.pointerId)return;e.preventDefault();const p=drag.node;p.x=Math.max(0,Math.min(2200,drag.x+e.clientX-drag.startX));p.y=Math.max(0,Math.min(8000,drag.y+e.clientY-drag.startY));b.style.left=p.x+'px';b.style.top=p.y+'px';$('#map-stage .map-links').outerHTML=C().mapSVG(map);};const end=e=>{if(!drag||drag.id!==e.pointerId)return;if(e.type==='pointercancel'){drag.node.x=drag.x;drag.node.y=drag.y;}drag=null;draw();persist();controls();};b.onpointerup=end;b.onpointercancel=end;b.onlostpointercapture=end;});$('#map-outline').innerHTML=C().mapHTML(map);};
 const panel=()=>{const p=current(),excluded=C().descendants(map,p.id);$('#map-label').value=p.label;$('#map-body').value=p.body;$('#map-relation').value=p.relation;$('#map-parent').innerHTML=p.parent===null?'<option>Central idea</option>':map.nodes.filter(p=>!excluded.has(p.id)).map(q=>`<option value="${q.id}" ${q.id===p.parent?'selected':''}>${c.esc(q.label||'Untitled thought')}</option>`).join('');$('#map-delete-choice').hidden=true;controls();};
 const select=id=>{selected=id;map.selected=id;draw();panel();};
 const focusNode=()=>{const p=current();$('#map-scroll').scrollTo({left:Math.max(0,p.x-30),top:Math.max(0,p.y-60),behavior:'instant'});};
 for(const [id,key]of [['map-label','label'],['map-body','body'],['map-relation','relation']]){let grouped=false;$('#'+id).onfocus=()=>{grouped=false;};$('#'+id).oninput=()=>{if(!grouped){remember();grouped=true;}current()[key]=$('#'+id).value;draw();persist();controls();};}
 $('#map-parent').onchange=()=>{const p=current(),parent=$('#map-parent').value;if(p.parent===null||C().descendants(map,p.id).has(parent))return;remember();p.parent=parent;draw();persist();controls();};$('#map-add').onclick=()=>{remember();try{const p=C().addBranch(map,selected,c.uid);selected=p.id;draw();panel();persist();focusNode();$('#map-label').focus();$('#map-label').select();}catch(e){c.toast(e.message);}};$('#map-arrange').onclick=()=>{remember();C().arrange(map);draw();panel();persist();focusNode();};$('#map-undo').onclick=()=>{if(!history.length)return;future.push(structuredClone(map.nodes));map.nodes=history.pop();if(!map.nodes.some(p=>p.id===selected))selected=map.nodes[0].id;draw();panel();persist();};$('#map-redo').onclick=()=>{if(!future.length)return;history.push(structuredClone(map.nodes));map.nodes=future.pop();if(!map.nodes.some(p=>p.id===selected))selected=map.nodes[0].id;draw();panel();persist();};
 $('#map-delete').onclick=()=>{const count=C().descendants(map,selected).size;$('#map-delete-copy').textContent=`Remove this thought${count>1?' and its '+(count-1)+' connected '+(count===2?'thought':'thoughts'):''}? Notes and tasks already created from it will stay.`;$('#map-delete-choice').hidden=false;$('#map-delete-cancel').focus();};$('#map-delete-cancel').onclick=()=>$('#map-delete-choice').hidden=true;$('#map-delete-confirm').onclick=()=>{if(current().parent===null)return;remember();const id=current().parent,remove=C().descendants(map,selected);map.nodes=map.nodes.filter(p=>!remove.has(p.id));selected=id;map.selected=id;draw();panel();persist();};
 for(const [id,task,key]of [['map-note',false,'noteId'],['map-task',true,'taskId']])$('#'+id).onclick=()=>{const p=current();persist();c.promote({id:p[key],title:p.label||'A thought to develop',text:p.body||p.label,task,parent:n,onId:id=>p[key]=id});};draw();panel();requestAnimationFrame(()=>{if($('#map-scroll'))focusNode();});c.icons();
}

function photo(n,c){const p=n.photo;let alive=true,busy=false,controller=null;
 shell(n,c,'Photo to text',`<p class="mode-lead">Keep the source. Make the words yours.</p><p class="hint">Choose a clear photo of printed text. Extraction runs on this device using the included Latin-script model. Review names, numbers and layout before using the text.</p><div class="photo-toolbar"><button id="photo-pick" class="secondary"><i data-lucide="image-plus"></i> Choose photo</button><input id="photo-file" type="file" accept="image/jpeg,image/png,image/webp" hidden><button id="photo-rotate" class="secondary"><i data-lucide="rotate-cw"></i> Rotate</button><button id="photo-extract" class="primary">Extract text</button><button id="photo-stop" class="secondary" hidden>Stop</button></div><div id="photo-status" class="mode-status" role="status">The original photo stays with this note. It is not sent to cloud AI.</div><div class="photo-grid"><section><h3>Source photo</h3><div id="photo-source" class="photo-source"></div><button id="photo-export-source" class="secondary">Export original photo</button></section><section><h3>Your text</h3><textarea id="photo-text" rows="14" maxlength="100000" aria-label="Editable extracted text" placeholder="Extracted text appears here. You can also type your own notes.">${c.esc(c.plain(n.html||''))}</textarea><details id="photo-blocks-section"><summary>Choose text blocks</summary><div id="photo-blocks"></div><button id="photo-use" class="secondary">Replace text with selected blocks</button><p class="hint">This replaces the draft above. Review your edits before using it.</p></details></section></div><p class="hint">Google ML Kit may send SDK diagnostics to Google; see Privacy &amp; data. Photos and recognized words stay on this device unless you choose to share the text through another feature.</p>`);
 const persist=common(n,c,()=>$('#photo-text').value.split('\n').map(line=>'<p>'+c.esc(line)+'</p>').join(''),()=>{alive=false;controller?.abort();});$('#photo-text').oninput=persist;
 const controls=()=>{for(const id of ['photo-pick','photo-rotate','photo-extract','photo-use','mode-done','mode-export'])$('#'+id).disabled=busy||(['photo-rotate','photo-extract'].includes(id)&&!p.data);$('#photo-stop').hidden=!controller;$('#photo-export-source').hidden=!p.data;};
 const blocks=()=>{$('#photo-blocks').innerHTML=p.blocks.map((b,i)=>`<label><input type="checkbox" data-photo-block="${i}" ${b.selected?'checked':''}><span>${c.esc(b.text)}</span></label>`).join('');$('#photo-blocks-section').hidden=!p.blocks.length;$$('[data-photo-block]').forEach(el=>el.onchange=()=>{p.blocks[Number(el.dataset.photoBlock)].selected=el.checked;source();persist();});};
 const source=()=>{$('#photo-source').innerHTML=p.data?`<img src="${c.esc(p.preview||p.data)}" alt="Original source for this note">${p.blocks.map((b,i)=>`<button class="photo-box ${b.selected?'chosen':''}" data-photo-box="${i}" style="left:${b.box[0]*100}%;top:${b.box[1]*100}%;width:${b.box[2]*100}%;height:${b.box[3]*100}%" aria-label="${b.selected?'Deselect':'Select'} text block ${i+1}">${i+1}</button>`).join('')}`:'<p class="hint">A receipt, a page, a sign, or a thought on paper.</p>';$$('[data-photo-box]').forEach(b=>b.onclick=()=>{const block=p.blocks[Number(b.dataset.photoBox)];block.selected=!block.selected;blocks();source();persist();});};
 $('#photo-pick').onclick=()=>$('#photo-file').click();$('#photo-file').onchange=async()=>{const file=$('#photo-file').files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>12*1024*1024){c.toast('Choose JPG, PNG or WebP smaller than 12 MB.');return;}busy=true;controls();$('#photo-status').textContent='Preparing the photo…';try{const data=await c.readData(file),preview=await NotaPhoto.prepare(data);if(!alive)return;p.data=data;p.preview=preview;p.rotation=0;p.blocks=[];source();blocks();persist();$('#photo-status').textContent='Photo ready. Your existing text is kept. Tap Extract text to read this image.';}catch(e){if(alive)$('#photo-status').textContent=e.message;}finally{if(alive){busy=false;controls();}}};
 $('#photo-rotate').onclick=async()=>{busy=true;controls();try{const rotation=(p.rotation+90)%360,preview=await NotaPhoto.prepare(p.data,rotation);if(!alive)return;p.rotation=rotation;p.preview=preview;p.blocks=[];source();blocks();persist();$('#photo-status').textContent='Photo rotated. Extract again to update the text blocks. Your edits are kept.';}catch(e){if(alive)$('#photo-status').textContent=e.message;}finally{if(alive){busy=false;controls();}}};
 $('#photo-extract').onclick=async()=>{busy=true;controller=new AbortController();controls();$('#photo-status').innerHTML='Reading the photo on this device…<progress aria-label="Reading photo text"></progress>';try{if(!p.preview)p.preview=await NotaPhoto.prepare(p.data,p.rotation);if(!alive)return;const result=await NotaPhoto.extract(p.preview,{signal:controller.signal,onProgress:d=>{if(alive)$('#photo-status').innerHTML=c.esc(d.message)+'<progress aria-label="Reading photo text"></progress>';}});if(!alive)return;p.blocks=(result.blocks||[]).slice(0,200).map(b=>({text:String(b.text).slice(0,10000),box:b.box.map(v=>Math.max(0,Math.min(1,Number(v)||0))),selected:true}));if(!$('#photo-text').value.trim())$('#photo-text').value=p.blocks.map(b=>b.text).join('\n\n').slice(0,100000);blocks();source();persist();$('#photo-status').textContent=p.blocks.length?`${p.blocks.length} text ${p.blocks.length===1?'block':'blocks'} found. Your edits are kept; selected blocks can replace the draft.`:'No readable text found. Try a clearer photo, better lighting or a closer view.';}catch(e){if(alive)$('#photo-status').textContent=e.name==='AbortError'?'Stopped. Your photo and text are saved.':e.message;}finally{if(alive){busy=false;controller=null;controls();}}};
 $('#photo-stop').onclick=()=>controller?.abort();$('#photo-use').onclick=()=>{const text=p.blocks.filter(b=>b.selected).map(b=>b.text).join('\n\n');if(!text){c.toast('Select at least one text block.');return;}$('#photo-text').value=text.slice(0,100000);persist();c.toast('Selected blocks copied into your note.');};$('#photo-export-source').onclick=()=>c.downloadPhoto(p.data,n.title);source();blocks();controls();c.icons();
}

window.NotaModeEditors={journal,math,mindmap,photo};
})();
